```js
app.get('/users/me', requireAuth, (req, res) => {
  const user = userDB.find(u => u.id === req.user.id);
  if (!user) return res.status(404).json({ error: 'Not found' });

  // Return only what the client needs — omit sensitive fields
  const { id, name, email } = user;
  res.json({ id, name, email });
});

// Admin-only full list
app.get('/users', requireAuth, requireRole('admin'), (req, res) => {
  res.json(userDB.map(({ id, name, email }) => ({ id, name, email })));
});
```

