```js
const cors = require('cors');

app.use(cors({
  origin: (origin, callback) => {
    const allowlist = ['https://yourapp.com', 'https://admin.yourapp.com'];
    if (!origin || allowlist.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS: origin not allowed'));
