No CORS headers are configured. Depending on deployment, this either blocks all cross-origin use or (if a permissive middleware is added later without care) allows any origin to make credentialed requests.

**Fix — define an explicit CORS allowlist:**

```js
const cors = require('cors');

const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',');

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS policy violation: origin ${origin} not allowed`));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400,
}));
```

