```js
const { z } = require('zod'); // or use express-validator, joi, etc.

app.use(express.json({ limit: '10kb' })); // parse bodies, cap size to prevent DoS

// Example: validate a query param before use
const userQuerySchema = z.object({
  id: z.coerce.number().int().positive(),
});

app.get('/users/:id', requireAuth, (req, res, next) => {
  const result = userQuerySchema.safeParse(req.params);
  if (!result.success) {
    return res.status(400).json({ error: 'Invalid user ID', details: result.error.issues });
  }
  const { id } = result.data;
  // safe to use `id` now
});
```

---

#### 6. 🟠 No Centralized Error Handling / Information Leakage (OWASP A09)

**Problem:** There is no error-handling middleware. Unhandled errors in Express will either crash the process or leak a full stack trace to the client (in default Express behavior), revealing internal paths, dependency versions, and logic details to attackers.

**Fix:** Always add a four-argument error handler as the last middleware, and distinguish between environments:

```js
// Must be registered AFTER all routes
app.use((err, req, res, next) => {
  const isProduction = process.env.NODE_ENV === 'production';

  // Log full error server-side (to your logging system, not console in prod)
  console.error(err);

  res.status(err.status || 500).json({
    error: isProduction
      ? 'An unexpected error occurred' // never leak internals to clients
      : err.message,
  });
});
```

